def bytes_to_bits(data):
    return ''.join(format(b, '08b') for b in data)

def bits_to_bytes(bits):
    return bytes(int(bits[i:i+8], 2) for i in range(0, len(bits), 8))

def rotate_bits_right(bits, n):
    n = n % len(bits)
    return bits[-n:] + bits[:-n]

